<?php require 'includes/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$id=trim($_POST['email']??'');$pw=$_POST['password']??'';$q=$pdo->prepare('SELECT * FROM faculty WHERE email=? LIMIT 1');$q->execute([$id]);$u=$q->fetch();if($u && password_verify($pw,$u['password']) && (int)$u['is_approved']===1){session_regenerate_id(true);$_SESSION['role']='faculty';$_SESSION['user_id']=$u['id'];$_SESSION['display_name']=$u['name'];go('faculty_dashboard.php');}else{flash('Invalid credentials or account is awaiting admin approval.');}} page_start('Faculty Login'); ?>
<div class="vc-card" style="max-width:520px;margin:auto"><h2>Faculty Login</h2><form method="post"><?php field('email','Email');field('password','Password','password');?><button class="btn btn-primary">Login</button></form></div><?php page_end(); ?>